function getThoughtspotTranslation(key, lang) {
    return (thoughtspotTranslations[lang] && thoughtspotTranslations[lang][key]) ||
           (thoughtspotTranslations.en && thoughtspotTranslations.en[key]) || null;
}

function applyThoughtspotTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.thoughtspot.") || key.startsWith("review.common."))) {
            const translation = getThoughtspotTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} thoughtspot translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyThoughtspotTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyThoughtspotTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyThoughtspotTranslations(window.i18n?.getCurrentLanguage() || "en");
}
